//
//  ShareViewController.swift
//
//  "Share → Latchet" from anywhere: a receipt photo, a screenshot of a payment
//  confirmation, or the text of one.
//
//  Copied into the Xcode project by plugins/withShareExtension.js. ios/ is
//  gitignored and regenerated by prebuild, so this file is the source of truth.
//
//  DELIBERATELY NOT REACT NATIVE. A share extension gets a small memory budget
//  and is killed without ceremony if it exceeds it; booting a JS runtime to
//  save one line would make the fast path the slow one. This is plain UIKit.
//
//  IT ALSO DOES NOT PARSE. The extension captures and queues; the app decides
//  what the content means when it next opens. Working out that "your payment of
//  $45.20" is an expense of 45.20 is done by quick-add.ts, which is tested —
//  re-implementing that in Swift would mean two parsers drifting apart, and the
//  Swift one could never be tested without a device.
//
import UIKit
import Social
import UniformTypeIdentifiers

/// Must match APP_GROUP in modules/app-group/index.ts and the entitlements.
private let appGroupIdentifier = "group.com.latchet.app"

private let queueFileName = "pending-shares.ndjson"
private let mediaDirectoryName = "shared-media"

/// Cap on the queue file, so a stuck share cannot fill the user's disk.
private let maxQueueBytes: UInt64 = 256 * 1024

/// Cap on one shared image. Receipts are photos, not raw captures.
private let maxImageBytes = 12 * 1024 * 1024

final class ShareViewController: SLComposeServiceViewController {

  /// Filled in as attachments load, written as one batch when the user posts.
  private var queuedLines: [String] = []

  override func isContentValid() -> Bool {
    // An image with no caption is a perfectly good receipt, so the text box
    // being empty is not a reason to disable Post.
    return true
  }

  override func presentationAnimationDidFinish() {
    // NSLocalizedString with no explicit bundle reads Bundle.main, which for
    // an extension is the extension's own bundle — the app's .lproj files are
    // in a different bundle entirely and never reach here.
    placeholder = NSLocalizedString(
      "share.placeholder",
      value: "Add a note, or an amount like 12.50",
      comment: "Placeholder in the share sheet's note field"
    )
  }

  override func didSelectPost() {
    let caption = (contentText ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
    let attachments = (extensionContext?.inputItems as? [NSExtensionItem])?
      .compactMap { $0.attachments }
      .flatMap { $0 } ?? []

    // Attachments load asynchronously and the extension must not complete
    // until they are all on disk, or the app finds queue lines pointing at
    // files that were never written.
    let group = DispatchGroup()

    for provider in attachments {
      if provider.hasItemConformingToTypeIdentifier(UTType.image.identifier) {
        group.enter()
        load(image: provider, caption: caption) { group.leave() }
      } else if provider.hasItemConformingToTypeIdentifier(UTType.url.identifier) {
        group.enter()
        load(url: provider) { group.leave() }
      }
    }

    group.notify(queue: .main) { [weak self] in
      guard let self else { return }
      // A caption on its own is a capture too — someone sharing nothing but
      // "18 lunch" from a notes app still means it.
      if self.queuedLines.isEmpty && !caption.isEmpty {
        self.enqueue(kind: "text", text: caption, file: nil)
      }
      self.flush()
      self.extensionContext?.completeRequest(returningItems: [], completionHandler: nil)
    }
  }

  // MARK: - Loading attachments

  private func load(image provider: NSItemProvider, caption: String, done: @escaping () -> Void) {
    provider.loadItem(forTypeIdentifier: UTType.image.identifier, options: nil) { [weak self] item, _ in
      defer { done() }
      guard let self else { return }

      // The system hands back a URL, a UIImage or raw Data depending on where
      // the share came from. All three are the same picture.
      var data: Data?
      var suggestedExtension = "jpg"

      if let url = item as? URL {
        data = try? Data(contentsOf: url)
        if !url.pathExtension.isEmpty { suggestedExtension = url.pathExtension }
      } else if let raw = item as? Data {
        data = raw
      } else if let image = item as? UIImage {
        data = image.jpegData(compressionQuality: 0.85)
      }

      guard let bytes = data, !bytes.isEmpty, bytes.count <= maxImageBytes else { return }
      guard let name = self.write(media: bytes, extension: suggestedExtension) else { return }
      self.enqueue(kind: "image", text: caption, file: name)
    }
  }

  private func load(url provider: NSItemProvider, done: @escaping () -> Void) {
    provider.loadItem(forTypeIdentifier: UTType.url.identifier, options: nil) { [weak self] item, _ in
      defer { done() }
      guard let self, let url = item as? URL else { return }
      // A file URL here is an image that did not declare itself as one; a web
      // URL is text as far as the app is concerned.
      guard !url.isFileURL else { return }
      self.enqueue(kind: "text", text: url.absoluteString, file: nil)
    }
  }

  // MARK: - Writing

  private func container() -> URL? {
    FileManager.default.containerURL(forSecurityApplicationGroupIdentifier: appGroupIdentifier)
  }

  /// Save one image into the shared container, returning the file name.
  private func write(media bytes: Data, extension ext: String) -> String? {
    guard let container = container() else { return nil }
    let directory = container.appendingPathComponent(mediaDirectoryName, isDirectory: true)
    try? FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)

    let name = UUID().uuidString + "." + (ext.isEmpty ? "jpg" : ext)
    do {
      try bytes.write(to: directory.appendingPathComponent(name), options: .atomic)
      return name
    } catch {
      return nil
    }
  }

  private func enqueue(kind: String, text: String, file: String?) {
    var payload: [String: Any] = [
      // Client-generated so a replayed drain cannot double-insert.
      "id": UUID().uuidString,
      "kind": kind,
      "text": text,
      "at": Int(Date().timeIntervalSince1970 * 1000),
    ]
    if let file { payload["file"] = file }

    guard
      let data = try? JSONSerialization.data(withJSONObject: payload, options: []),
      let line = String(data: data, encoding: .utf8)
    else { return }
    queuedLines.append(line)
  }

  /// Append every queued line in one write.
  ///
  /// Newline-delimited, for the same reason the Siri queue is: appending from a
  /// separate process must not be a read-modify-write, and a torn final line
  /// should cost one entry rather than the file.
  private func flush() {
    guard !queuedLines.isEmpty, let container = container() else { return }
    let url = container.appendingPathComponent(queueFileName)
    guard let payload = (queuedLines.joined(separator: "\n") + "\n").data(using: .utf8) else { return }

    guard FileManager.default.fileExists(atPath: url.path) else {
      try? payload.write(to: url, options: .atomic)
      return
    }

    let attributes = try? FileManager.default.attributesOfItem(atPath: url.path)
    let size = (attributes?[.size] as? NSNumber)?.uint64Value ?? 0
    if size > maxQueueBytes { return }

    guard let handle = try? FileHandle(forWritingTo: url) else { return }
    defer { try? handle.close() }
    try? handle.seekToEnd()
    try? handle.write(contentsOf: payload)
  }
}
